(()=>{(()=>{if(window.__nlTtMain)return;window.__nlTtMain=!0;let OUT="nl-tt-main",IN="nl-tt-iso",backlog=[],ready=!1,giftList=null,open=new Map,post=msg=>{if(!ready){backlog.push(msg),backlog.length>400&&backlog.shift();return}try{window.postMessage({source:OUT,...msg},location.origin)}catch{}},roomIdOf=url=>{try{let u=new URL(String(url||""),location.href);if(u.protocol!=="wss:"||!/^webcast[^.]*\.(?:[a-z0-9-]+\.)*tiktok\.com$/i.test(u.hostname))return"";let r=String(u.searchParams.get("room_id")||"");return/^\d{5,20}$/.test(r)?r:""}catch{return""}},watch=(ws,url)=>{let roomId=roomIdOf(url);roomId&&(open.set(ws,roomId),post({t:"open",roomId,at:Date.now()}),ws.addEventListener("message",ev=>{let d=ev.data;d instanceof ArrayBuffer?post({t:"frame",roomId,buf:d}):d instanceof Blob&&d.arrayBuffer().then(buf=>post({t:"frame",roomId,buf})).catch(()=>{})}),ws.addEventListener("close",()=>{open.delete(ws),post({t:"close",roomId,at:Date.now()})}))},Native=window.WebSocket;typeof Native=="function"&&(window.WebSocket=new Proxy(Native,{construct(target,args,newTarget){let ws=Reflect.construct(target,args,newTarget);try{watch(ws,args[0])}catch{}return ws}}));let takeGiftList=json=>{let gifts=json?.data?.gifts;if(!Array.isArray(gifts)||!gifts.length)return;let pick=img=>Array.isArray(img?.url_list)?img.url_list.slice(0,2):[];giftList={data:{gifts:gifts.slice(0,3e3).map(g=>({id:g?.id,name:g?.name,diamond_count:g?.diamond_count,combo:g?.combo,type:g?.type,image:{url_list:pick(g?.image)},icon:{url_list:pick(g?.icon)}}))}},post({t:"gifts",json:giftList})},GIFT_RE=/\/webcast\/gift\/list\//,nativeFetch=window.fetch;typeof nativeFetch=="function"&&(window.fetch=function(input,init){let p=nativeFetch.call(this,input,init);try{let url=typeof input=="string"?input:String(input?.url||"");GIFT_RE.test(url)&&p.then(r=>r.clone().json()).then(takeGiftList).catch(()=>{})}catch{}return p});let XO=XMLHttpRequest.prototype.open;XMLHttpRequest.prototype.open=function(method,url){try{GIFT_RE.test(String(url||""))&&this.addEventListener("load",()=>{try{let body=this.responseType==="json"?this.response:this.responseType===""||this.responseType==="text"?JSON.parse(this.responseText):null;body&&takeGiftList(body)}catch{}})}catch{}return XO.apply(this,arguments)},window.addEventListener("message",ev=>{if(ev.source!==window||ev.data?.source!==IN||ev.data?.t!=="hello")return;ready=!0;let list=backlog;backlog=[],post({t:"state",rooms:[...open.values()]}),giftList&&post({t:"gifts",json:giftList});for(let m of list)m.t!=="gifts"&&post(m)})})();})();
